Record Producto
  Define nombre As String;
  Define precio, stock As Integer;
EndRecord

Function importe <- Importe(precio As Integer, cantidad As Integer)
  Define importe As Integer;
  importe <- precio * cantidad;
EndFunction

Function monto <- ConDescuento(total As Integer)
  Define monto As Integer;
  monto <- total - total Div 10;
EndFunction

Function valido <- CodigoValido(codigo As Integer)
  Define valido As Boolean;
  valido <- codigo >= 1 And codigo <= 5;
EndFunction

Function texto <- InventarioJson(productos As Vector<Producto>)
  Define texto As String <- "{";
  For Each producto In productos Do
    If texto <> "{" Then
      texto <- texto + ", ";
    EndIf
    texto <- texto + '"' + producto.nombre + '": ' + toText(producto.stock);
  EndFor
  texto <- texto + "}";
EndFunction

Subroutine Catalogo() As Vector<Producto>
  Define productos As Vector<Producto> <- vector();
  productos.append(Producto("Jugo", 3, 10));
  productos.append(Producto("Sándwich", 5, 5));
  productos.append(Producto("Alfajor", 2, 8));
  productos.append(Producto("Agua", 1, 12));
  productos.append(Producto("Fruta", 2, 6));
  Return productos;
EndSubroutine

Function stock <- StockGuardado(inventario As JsonValue, producto As Producto)
  Define stock As Integer <- producto.stock;
  Switch inventario.field(producto.nombre) Do
    Some(valor):
      Switch valor.asInteger() Do
        Some(guardado): stock <- guardado;
        None: stock <- producto.stock;
      EndSwitch
    None: stock <- producto.stock;
  EndSwitch
EndFunction

Function cargados <- AplicarInventario(productos As Vector<Producto>, inventario As JsonValue)
  Define cargados As Vector<Producto> <- vector();
  For Each producto In productos Do
    cargados.append(Producto(producto.nombre, producto.precio, StockGuardado(inventario, producto)));
  EndFor
EndFunction

Subroutine CargarInventario() As Result<String, IoError>
  Define carpeta As DirCap <- Propagate requestDirectory(".");
  Define archivo As FileCap <- Propagate carpeta.open("inventario.json", "lectura");
  Defer
    Discard archivo.close();
  EndDefer
  Return archivo.readText();
EndSubroutine

Subroutine GuardarInventario(texto As String) As Result<Integer, IoError>
  Define carpeta As DirCap <- Propagate requestDirectory(".");
  Define archivo As FileCap <- Propagate carpeta.open("inventario.json", "escritura");
  Defer
    Discard archivo.close();
  EndDefer
  Return archivo.writeText(texto);
EndSubroutine

Algorithm Kiosco
  Define productos As Vector<Producto> <- Catalogo();
  Switch CargarInventario() Do
    Success(texto):
      Switch parseJson(texto) Do
        Success(inventario):
          productos <- AplicarInventario(productos, inventario);
          Write "Inventario cargado";
        Failure(roto): Write "Inventario roto en la columna ", roto.jsonColumn, ": stock inicial";
      EndSwitch
    Failure(problema): Write "Sin inventario guardado (", problema.code, "): stock inicial";
  EndSwitch
  Define total As Integer <- 0;
  Define codigo, cantidad As Integer;
  Read codigo;
  While codigo <> 0 Do
    Read cantidad;
    If Not CodigoValido(codigo) Then
      Write "Código ", codigo, " no existe";
    Else
      If cantidad < 1 Then
        Write "Cantidad ", cantidad, " no válida";
      Else
        Define producto As Producto <- productos[codigo - 1];
        If cantidad > producto.stock Then
          Write producto.nombre, " x ", cantidad, " rechazado: quedan ", producto.stock;
        Else
          producto.stock <- producto.stock - cantidad;
          productos[codigo - 1] <- producto;
          Write producto.nombre, " x ", cantidad, " = ", Importe(producto.precio, cantidad);
          total <- total + Importe(producto.precio, cantidad);
        EndIf
      EndIf
    EndIf
    Read codigo;
  EndWhile
  Write "Total: ", total;
  Write "Con descuento: ", ConDescuento(total);
  Switch GuardarInventario(InventarioJson(productos)) Do
    Success(bytes): Write "Inventario guardado: ", bytes, " bytes";
    Failure(problema): Write "No se pudo guardar: ", problema.code;
  EndSwitch
EndAlgorithm

